hints.text:
Una tienda quiere saber qué tres días seguidos vendió más.

function mejoresDias(ventas, n) {
  if (n < 1 || n > ventas.length) return null;
  let suma = 0;
  for (let i = 0; i < n; i++) suma += ventas[i];
  let mejor = suma;
  for (let i = n; i < ventas.length; i++) {
    suma += ventas[i] - ventas[i - n];
    if (suma > mejor) mejor = suma;
  }
  return mejor;
}
